import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Panel, PanelHeader, PanelTitle, PanelTitleSup } from "@/components/panel";
import { PostSearch } from "@/components/post-search";
import { getPublishedPosts } from "@/lib/blog";
import { serializeJsonLd } from "@/lib/json-ld";
import { site } from "@/lib/site";

/**
 * With nothing published the route 404s, so it must not advertise itself as a
 * Blog — naming a page the Visitor cannot reach is a lie told by the tab.
 */
export function generateMetadata(): Metadata {
  if (getPublishedPosts().length === 0) return { title: "Nothing lives here" };
  return {
    title: "Blog",
    alternates: { canonical: `${site.url}/blog` },
  };
}

export default function BlogPage() {
  // Nothing empty is ever shown to a Visitor (CONTEXT.md → Blog / Post).
  const posts = getPublishedPosts();
  if (posts.length === 0) notFound();

  // The body is the one thing a row never draws, and the rows are drawn in the
  // browser here — so it is dropped before the list crosses over rather than
  // shipped down and ignored.
  const summaries = posts.map(({ content: _content, ...summary }) => summary);

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Blog",
    "@id": `${site.url}/blog`,
    name: "Blog",
    url: `${site.url}/blog`,
    author: { "@type": "Person", name: site.name, url: site.url },
    blogPost: posts.map((post) => ({
      "@type": "BlogPosting",
      "@id": `${site.url}/blog/${post.slug}`,
      headline: post.title,
      description: post.summary,
      url: `${site.url}/blog/${post.slug}`,
      datePublished: post.publishedAt,
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
      />

      {/* One panel, not a heading floating above a list: the index is a single
          thing on the page, and the site draws single things inside rails.
          There is no tagline under the title — the reference needs one because
          its heading *is* the tagline; ours says the word the nav promised and
          then gets out of the way of the posts. */}
      <Panel id="blog">
        <PanelHeader>
          <PanelTitle as="h1">
            Blog
            <PanelTitleSup className="tabular-nums">
              {posts.length}
            </PanelTitleSup>
          </PanelTitle>
        </PanelHeader>

        <PostSearch posts={summaries} />
      </Panel>
    </>
  );
}

--- BLOG SECTION ---
import { CopyLink } from "@/components/copy-link";
import { MoreLink } from "@/components/more-link";
import {
  Panel,
  PanelHeader,
  PanelTitle,
  PanelTitleSup,
} from "@/components/panel";
import { PostItem } from "@/components/post-item";
import { getPublishedPosts } from "@/lib/blog";

/** How many Posts the home page carries before it defers to `/blog`. */
export const HOME_POST_LIMIT = 5;

/**
 * On the home page this is the latest few with a door at the bottom; on
 * `/blog` it is everything and the door is gone. Same rows either way — the
 * page decides how many, the row decides nothing.
 */
export function BlogSection({
  limit,
  as = "h2",
}: {
  limit?: number;
  as?: "h1" | "h2";
}) {
  const posts = getPublishedPosts();
  const shown = limit ? posts.slice(0, limit) : posts;
  const hidden = posts.length - shown.length;

  return (
    <Panel id="blog">
      <PanelHeader>
        <PanelTitle as={as}>
          Blog
          <PanelTitleSup className="tabular-nums">{posts.length}</PanelTitleSup>
          <CopyLink id="blog" label="Blog" />
        </PanelTitle>
      </PanelHeader>

      <ul>
        {shown.map((post) => (
          <PostItem
            key={post.slug}
            post={post}
            headingAs={as === "h1" ? "h2" : "h3"}
          />
        ))}
      </ul>

      {hidden > 0 ? <MoreLink href="/blog">All posts</MoreLink> : null}
    </Panel>
  );
}

--- POST ITEM ---
import Image from "next/image";
import Link from "next/link";
import { formatPostDate, type PostSummary } from "@/lib/posts";

/**
 * One Post, as a row across the page.
 *
 * The reference draws Posts as cards in two columns, and it is right to: every
 * one of its Posts ships a 1200×630 cover, and a grid of pictures is what a
 * grid is for. Ours ship none, and a card with no picture is a row that has
 * been put in a box — half the width, so the summary breaks after four words,
 * and at one Post it is a card beside a hole.
 *
 * So the picture is optional and the row is not. When a cover exists it leads
 * the row as a 16:9 plate; when it does not, the row is a title, a sentence and
 * two facts, which is the same shape a Project row has. That is the site's
 * idiom — things on rules, full width — and it reads the same at one Post as at
 * fifty.
 */
export function PostItem({
  post,
  headingAs = "h2",
}: {
  post: PostSummary;
  headingAs?: "h2" | "h3";
}) {
  const Heading = headingAs;

  return (
    <li className="border-b border-line last:border-b-0">
      {/* `relative` scopes the stretched link to this row, so the next Post's
          title never falls under this one's target. */}
      <div className="group/post relative flex items-start gap-4 p-4 transition-[background-color] duration-150 ease-out hover:bg-accent-muted">
        {post.image ? (
          <div className="relative w-28 shrink-0 select-none max-sm:hidden">
            {/* Grey until the pointer is on it: colour is the reward for
                choosing this one, not a thing six rows shout at once. */}
            <Image
              className="aspect-1200/630 rounded-lg grayscale transition-[filter] duration-300 ease-out group-hover/post:grayscale-0"
              src={post.image}
              alt=""
              width={1200}
              height={630}
              quality={100}
              unoptimized
            />
            <div className="pointer-events-none absolute inset-0 rounded-lg inset-ring-1 inset-ring-black/15 dark:inset-ring-white/15" />
          </div>
        ) : null}

        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <Heading className="leading-snug font-medium text-balance">
            <Link href={`/blog/${post.slug}`}>
              <span aria-hidden className="absolute inset-0" />
              {post.title}
            </Link>
          </Heading>

          <p className="typeset typeset-description text-muted-foreground">
            {post.summary}
          </p>

          {/* Date and length, in the same mono the rest of the site measures
              things in. A `dl` because they are facts about the Post, not two
              more pieces of its prose. */}
          <dl className="mt-1 flex items-center gap-2 font-mono text-xs text-muted-foreground/80 tabular-nums">
            <dt className="sr-only">Published on</dt>
            <dd>
              <time dateTime={post.publishedAt}>
                {formatPostDate(post.publishedAt)}
              </time>
            </dd>
            <span aria-hidden>·</span>
            <dt className="sr-only">Reading time</dt>
            <dd>{post.readingTimeMinutes} min read</dd>
          </dl>
        </div>
      </div>
    </li>
  );
}

--- POST SEARCH ---
"use client";

import { useMemo, useState } from "react";
import { PostItem } from "@/components/post-item";
import { SearchField, SearchStatus } from "@/components/search-field";
import { searchPosts, type PostSummary } from "@/lib/posts";

/**
 * The index, with a filter over it.
 *
 * The reference keeps its query in the URL, which buys a shareable search and
 * costs a query-state dependency, a Suspense boundary and a router write on
 * every keystroke. A filter over a list this size is a glance, not a
 * destination — nobody sends a friend a link to a filtered blog index — so the
 * query lives in the component and the URL stays the address of the page.
 *
 * The list is not virtualised and does not need to be: it is filtering an
 * array that was already sent, in memory, with no request behind it.
 */
export function PostSearch({ posts }: { posts: PostSummary[] }) {
  const [query, setQuery] = useState("");
  const shown = useMemo(() => searchPosts(posts, query), [posts, query]);

  return (
    <>
      <SearchField
        value={query}
        onChange={setQuery}
        label="Search posts"
        placeholder="Search posts…"
      />
      <SearchStatus count={shown.length} noun="post" />

      {shown.length > 0 ? (
        <ul>
          {shown.map((post) => (
            <PostItem key={post.slug} post={post} headingAs="h2" />
          ))}
        </ul>
      ) : (
        <p className="p-4 font-mono text-sm text-muted-foreground">
          No posts match “{query}”.
        </p>
      )}
    </>
  );
}

