  @apply inline-flex h-8 min-w-8 items-center justify-center gap-1.5 rounded-lg px-2 text-sm text-muted-foreground transition-colors select-none active:scale-[0.98] hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40 dark:hover:bg-accent/50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0;
