/* ---------------------------------------------------------------------------
   Typeset — the two long-form measures. `--typeset-flow` is the vertical
   rhythm between blocks, expressed in the block's own em so it scales with
   the measure rather than the root.
--------------------------------------------------------------------------- */

.typeset {
  --typeset-size: 1rem;
  --typeset-leading: 1.65;
  --typeset-flow: 1.25em;

  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  text-wrap: pretty;
}

.typeset > * + * {
  margin-top: var(--typeset-flow);
}

.typeset-description {
  --typeset-size: 15px;
  --typeset-leading: 1.6;
  --typeset-flow: 1em;
}

.typeset-timescale {
  --typeset-size: 0.875rem;
  --typeset-leading: 1.5;
  --typeset-flow: 1em;
}

/* ---------------------------------------------------------------------------
   Entrance. The frame is drawn instantly; only the mosaic and the palette
   fade, and neither loops.
--------------------------------------------------------------------------- */

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Written out rather than run as `fade-in … reverse`: reversing an animation
   that has already finished does not restart it, it re-reads the same finished
   playhead against the other end of the timeline — so the element snaps to the
   far keyframe instead of travelling to it. An exit needs its own name. */
@keyframes fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

/* ---------------------------------------------------------------------------
   Activity mosaic. Square blocks on a 2px gutter, no corner rounding — the
   grid is a measuring instrument, so its cells are not decorated. Intensity
   is carried by the neutral foreground at five opacities.

   Every measurement here is the reference's: a 12px block on a 2px gutter,
   under a 22px label band. They are not arbitrary — a rolling year at that
   size is a fixed 740px plate, the same shape every month of every year, which
   is the whole point of drawing a habit as a calendar. A cell that grew to
   fill the rail would make the same year a different picture each visit.
--------------------------------------------------------------------------- */

.activity-grid {
  --cell-size: 12px;
  --cell-gap: 2px;
  --label-size: 12px;
  display: grid;
  /* A length, not a fraction. A `1fr` track lets the browser round one week
     to 12px and the next to 13, which on a grid of squares reads as a wobble
     in every row. */
  grid-template-columns: repeat(var(--weeks, 53), var(--cell-size));
  gap: var(--cell-gap);
  /* The grid is one tab stop, but the thing that moves is the active cell, so
     the ring is drawn there instead of around all 365 of them. */
  outline: none;
  /* Room for that ring, so it cannot cross the panel's vertical rail. */
  padding-inline: 3px;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, var(--cell-size));
  gap: var(--cell-gap);
  /* The label band: the type size plus the 8px of air the reference leaves
     under it, so the months sit above the plate rather than on it. */
  padding-top: calc(var(--label-size) + 8px);
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: var(--label-size);
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  pointer-events: none;
}

/* The strip is wider than a phone, so it is dragged rather than trimmed. The edge fades are driven by the scroll position itself: each side
   is masked only while there is more grid past it, so a strip that fits shows
   no fade at all and a strip scrolled to its end stops advertising an end. */
@property --activity-fade-s {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@property --activity-fade-e {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@keyframes activity-fade-s {
  from {
    --activity-fade-s: 0px;
  }
  to {
    --activity-fade-s: var(--activity-fade);
  }
}
@keyframes activity-fade-e {
  from {
    --activity-fade-e: var(--activity-fade);
  }
  to {
    --activity-fade-e: 0px;
  }
}

.activity-scroll {
  --activity-fade: 2.5rem;
  display: flex;
  /* The same gutter every other row in the panel keeps, so the first and last
     week line up with the caption above them rather than with the rail. */
  padding-inline: 1rem;
  /* Centred while the year fits the rail, flush-left once it does not —
     `safe` is what keeps the first week reachable instead of centring it off
     the scrollable edge. */
  justify-content: safe center;
  overflow-x: auto;
  overflow-y: hidden;
  /* The grid is a drawing; a scrollbar drawn under it would read as part of
     the figure. The strip still scrolls by drag, wheel and keyboard. */
  scrollbar-width: none;
  mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 var(--activity-fade-s),
    #000 calc(100% - var(--activity-fade-e)),
    transparent 100%
  );
  animation:
    activity-fade-s 1ms linear both,
    activity-fade-e 1ms linear both;
  animation-timeline: scroll(self inline), scroll(self inline);
  animation-range:
    0 var(--activity-fade),
    calc(100% - var(--activity-fade)) 100%;
}

.activity-scroll::-webkit-scrollbar {
  display: none;
}

.activity-cell {
  background: color-mix(
    in oklab,
    var(--muted-foreground) var(--level, 10%),
    transparent
  );
  position: relative;
  width: var(--cell-size);
  height: var(--cell-size);
  animation: fade-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
  /* No transition on the marker. A cursor that fades in over a tenth of a
     second reads as the grid thinking about it; the cursor is where the
     pointer is, and that is true on the frame the pointer arrives. */
  outline: 1px solid transparent;
  outline-offset: 1px;
}

/* Pointer: a hairline marker. Keyboard: the site's own focus ring, moved onto
   the active descendant so focus keeps the same shape it has everywhere else. */
.activity-cell[data-active="true"] {
  outline-color: var(--foreground);
}

.activity-grid:focus-visible .activity-cell[data-active="true"] {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}

/* An empty frame rather than a fill. Only Figure 404 draws these now: inside
   the activity window an absent day is a measured zero, because the meter
   reads every session on the machine. */
.activity-cell[data-recorded="false"] {
  background: transparent;
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--muted-foreground) 16%, transparent);
}

/* ---------------------------------------------------------------------------
   A single sweep of light across a line of text, once, on load. The gradient
   is painted into the glyphs themselves and slid from right to left, so the
   highlight travels the line rather than the line changing colour. Spread is
   in `ch` so it scales with the type, and the background is twice the element
   plus two spreads wide so the sweep starts and ends fully off the text.
--------------------------------------------------------------------------- */
@keyframes shimmer-sweep {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: 0 0;
  }
}

.shimmer {
  --shimmer-spread: calc(3ch + 40px);
  --shimmer-angle: 20deg;
  background-image: linear-gradient(
    calc(90deg + var(--shimmer-angle)),
    currentColor calc(50% - var(--shimmer-spread)),
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% - var(--shimmer-spread) * 0.5),
    var(--foreground) 50%,
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% + var(--shimmer-spread) * 0.5),
    currentColor calc(50% + var(--shimmer-spread))
  );
  background-repeat: no-repeat;
  background-size: calc(200% + var(--shimmer-spread) * 2) 100%;
  background-position: 0 0;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer-sweep 1.5s linear 1;
}

/* Motion is the whole effect, so with it turned off there is nothing left to
   show — paint the text normally rather than leaving it in a frozen gradient. */
@media (prefers-reduced-motion: reduce) {
  .shimmer {
    background-image: none;
    animation: none;
    -webkit-text-fill-color: currentColor;
  }
}

/* ---------------------------------------------------------------------------
   Name pronunciation. The speaker's two waves pulse while the name is being
   said, offset so they read as leaving the cone rather than blinking together.
   Nothing else moves: the glyph is the state, so it must not also be a toy.
--------------------------------------------------------------------------- */
@keyframes pronounce-wave {
  0%,
  100% {
    opacity: 0.3;
  }
  50% {
    opacity: 1;
  }
}

[data-slot="pronounce"][data-speaking] [data-wave="near"] {
  animation: pronounce-wave 0.9s ease-in-out infinite;
}

[data-slot="pronounce"][data-speaking] [data-wave="far"] {
  animation: pronounce-wave 0.9s ease-in-out 0.15s infinite;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="pronounce"][data-speaking] [data-wave] {
    animation: none;
  }
}

/* ---------------------------------------------------------------------------
   The bottom edge of the sheet. Fixed, so it is the last thing every scroll
   runs into: the page dissolves into the background over six rems, and the
   gradient is itself masked from the top so the fade has no visible start.
   The strip below it is opaque background padded by the home indicator, which
   is what the floating palette dock rests on.
--------------------------------------------------------------------------- */
.fade-bottom {
  position: fixed;
  inset-inline: 0;
  bottom: 0;
  z-index: 50;
  pointer-events: none;
}

.fade-bottom-gradient {
  height: var(--fade-bottom-height);
  background: linear-gradient(to bottom, transparent, var(--background));
  mask-image: linear-gradient(to top, var(--background) 25%, transparent);
  backdrop-filter: blur(1px);
}

.fade-bottom-rest {
  background: var(--background);
  padding-bottom: env(safe-area-inset-bottom, 0px);
}

/* ---------------------------------------------------------------------------
   Figure 404. Drawn from the same cells as the activity grid, at plate scale:
   the page that has no data says so in the site's own word for it. Cells size
   themselves off the column rather than off a fixed pixel, so the plate is the
   full width of the frame at every viewport.
--------------------------------------------------------------------------- */
.glyph-grid {
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
  gap: 2px;
  width: 100%;
}

.glyph-grid > * {
  aspect-ratio: 1;
}

/* ---------------------------------------------------------------------------
   Prose (MDX) — long-form runs on the serif; structure stays sans.
--------------------------------------------------------------------------- */

.prose {
  /* One step up from the interface size. The serif runs to ~76 characters at
     16px in this frame, which is past the line a reader can return from
     without losing their place; the extra pixel pulls it back to ~72. */
  --typeset-size: 1.0625rem;
  font-family: var(--font-serif);
  color: var(--foreground);
}
.prose h2,
.prose h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  letter-spacing: -0.01em;
  scroll-margin-top: calc(var(--header-height) + 1rem);
}
.prose h2 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
}
.prose > :first-child {
  margin-top: 0;
}
.prose a {
  color: var(--link);
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 150ms var(--ease-out-quint);
}
.prose a:hover {
  text-decoration-color: currentColor;
}
.prose strong {
  font-weight: 600;
}
.prose ul,
.prose ol {
  padding-left: 1.25rem;
}
.prose ul {
  list-style: disc;
}
.prose ol {
  list-style: decimal;
}
.prose li::marker {
  color: var(--muted-foreground);
}
.prose li + li {
  margin-top: 0.5rem;
}
.prose blockquote {
  padding-left: 1.125rem;
  border-left: 2px solid var(--border);
  color: var(--muted-foreground);
  font-style: italic;
}
.prose hr {
  border: 0;
  border-top: 1px solid var(--line);
}

--- PANEL ---
import { cn } from "@/lib/utils";

/**
 * The page is a stack of panels sharing one vertical rail. A panel draws its
 * own left/right edges and a full-bleed hairline top and bottom, so the frame
 * continues past the content column to the edge of the viewport. Everything
 * on the site is composed from these six parts — there is no other container.
 */
export function Panel({ className, ...props }: React.ComponentProps<"section">) {
  return (
    <section
      data-slot="panel"
      className={cn(
        "screen-line-top screen-line-bottom border-x border-line",
        className,
      )}
      {...props}
    />
  );
}

export function PanelHeader({
  className,
  ...props
}: React.ComponentProps<"header">) {
  return (
    <header
      data-slot="panel-header"
      className={cn(
        "screen-line-bottom px-4 has-data-[slot=panel-description]:*:data-[slot=panel-title]:screen-line-bottom",
        className,
      )}
      {...props}
    />
  );
}

/**
 * A panel title is an `h2` because the usual panel is one section of a page
 * that already has its own `h1`. A page whose whole content *is* one panel —
 * a post, the blog index, the 404 — passes `as="h1"` so the document keeps a
 * top-level heading and the panel's own sub-headings still rank below it.
 */
export function PanelTitle({
  as: Tag = "h2",
  className,
  ...props
}: React.ComponentProps<"h2"> & { as?: "h1" | "h2" }) {
  return (
    <Tag
      data-slot="panel-title"
      className={cn(
        "group/panel-title font-heading text-3xl font-medium tracking-tight text-balance",
        className,
      )}
      {...props}
    />
  );
}

/** The count or unit that rides above the baseline of a title. */
export function PanelTitleSup({
  className,
  ...props
}: React.ComponentProps<"sup">) {
  return (
    <sup
      className={cn(
        "top-[-0.75em] ml-1 text-sm font-medium tracking-normal text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

export function PanelDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="panel-description"
      className={cn(
        "py-4 text-base text-balance text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

export function PanelContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div data-slot="panel-body" className={cn("p-4", className)} {...props} />
  );
}

--- SEARCH FIELD ---
"use client";

import { CloseIcon, SearchIcon } from "@/components/icons";

/**
 * The filter above a list. One field, used by the blog index and the projects
 * index, so the two pages type the same way — the second search box a Visitor
 * meets should teach them nothing new.
 *
 * It owns no state: the list it filters does, because the list is the thing
 * that has to re-render. See `PostSearch` and `ProjectSearch`.
 */
export function SearchField({
  value,
  onChange,
  label,
  placeholder,
}: {
  value: string;
  onChange: (value: string) => void;
  label: string;
  placeholder: string;
}) {
  return (
    <div className="screen-line-bottom p-2">
      <div className="relative flex items-center">
        <SearchIcon
          aria-hidden
          className="pointer-events-none absolute left-3 size-4 text-muted-foreground"
        />
        <input
          type="search"
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={(event) => {
            // Escape empties the field before it does anything else — the same
            // key the palette closes with, doing the same job here.
            if (event.key === "Escape" && value) {
              event.preventDefault();
              onChange("");
            }
          }}
          placeholder={placeholder}
          aria-label={label}
          autoComplete="off"
          spellCheck={false}
          /* 16px on a phone: anything smaller and iOS zooms the page on focus,
             which lands the Visitor somewhere they did not ask to be. */
          className="h-9 w-full rounded-lg border border-border bg-transparent pr-9 pl-9 text-base text-foreground placeholder:text-muted-foreground sm:text-sm dark:bg-input/30"
        />
        {value ? (
          <button
            type="button"
            onClick={() => onChange("")}
            aria-label="Clear search"
            className="absolute right-1.5 flex size-6 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:text-foreground"
          >
            <CloseIcon className="size-4" />
          </button>
        ) : null}
      </div>
    </div>
  );
}

/**
 * What a filter did, for someone who cannot see the list change shape. The
 * count is the whole message: a screen reader announcing every matching title
 * on every keystroke is worse than silence.
 */
export function SearchStatus({
  count,
  noun,
}: {
  count: number;
  noun: string;
}) {
  return (
    <p role="status" className="sr-only">
      {count === 1 ? `1 ${noun}` : `${count} ${noun}s`}
    </p>
  );
}

--- LAYOUT ---
import type { Metadata, Viewport } from "next";
import { GeistSans } from "geist/font/sans";
import { GeistMono } from "geist/font/mono";
import { Caveat, IBM_Plex_Serif } from "next/font/google";
import { Analytics } from "@vercel/analytics/next";
import { SpeedInsights } from "@vercel/speed-insights/next";
import { CommandPaletteProvider } from "@/components/command-palette";
import { MobileDock } from "@/components/mobile-dock";
import { ThemeColor } from "@/components/theme-color";
import { ThemeProvider } from "@/components/theme-provider";
import { SiteHeader } from "@/components/site-header";
import { SiteFooter } from "@/components/site-footer";
import { ScrollToTop } from "@/components/scroll-to-top";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { getPublishedPosts } from "@/lib/blog";
import { navItems } from "@/lib/nav";
import { paletteItems } from "@/lib/palette";
import { ogImagePath } from "@/lib/discovery";
import { serializeJsonLd } from "@/lib/json-ld";
import { profileUrls, site } from "@/lib/site";
import "./globals.css";

/** Long-form prose only. Structure and UI stay on the sans. */
const plexSerif = IBM_Plex_Serif({
  subsets: ["latin"],
  weight: ["400", "500", "600"],
  style: ["normal", "italic"],
  display: "swap",
  variable: "--font-plex-serif",
});

/** Marginalia — annotations that read as a hand, never as body copy. */
const caveat = Caveat({
  subsets: ["latin"],
  weight: ["400", "600"],
  display: "swap",
  variable: "--font-caveat",
});

export const metadata: Metadata = {
  metadataBase: new URL(site.url),
  title: {
    default: `${site.name} — ${site.tagline}`,
    template: `%s · ${site.name}`,
  },
  description: site.description,
  openGraph: {
    title: site.name,
    description: site.description,
    url: site.url,
    siteName: site.name,
    type: "website",
    images: [{ url: ogImagePath(site.name) }],
  },
  twitter: {
    card: "summary_large_image",
    title: site.name,
    description: site.description,
    images: [ogImagePath(site.name)],
  },
  alternates: {
    // The auto-discovery link. It is what lets a reader be handed
    // `dhruv2mars.com` and find the feed on its own, which is how most people
    // subscribe — they never see `/feed.xml`. The title is what the reader
    // then files it under.
    types: {
      "application/rss+xml": [
        { url: site.rssPath, title: `${site.name} — Blog` },
      ],
    },
  },
};

export const viewport: Viewport = {
  /* The dock at the foot of the page pads itself with
     `env(safe-area-inset-bottom)`, and that variable is zero on iOS unless the
     page has opted out of the safe-area letterbox first. */
  viewportFit: "cover",
  themeColor: [
    { media: "(prefers-color-scheme: dark)", color: "#09090b" },
    { media: "(prefers-color-scheme: light)", color: "#ffffff" },
  ],
};

const jsonLd = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      name: site.name,
      url: site.url,
      description: site.description,
      author: { "@type": "Person", name: site.name, url: site.url },
    },
    {
      "@type": "Person",
      name: site.name,
      url: site.url,
      jobTitle: site.tagline,
      sameAs: profileUrls(),
    },
  ],
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const posts = getPublishedPosts();
  const hasPosts = posts.length > 0;

  return (
    <html
      lang="en"
      className={`preload ${GeistSans.variable} ${GeistMono.variable} ${plexSerif.variable} ${caveat.variable}`}
      suppressHydrationWarning
    >
      <body>
        {/* Two things that must be settled before the first paint: drop
            `.preload` so the stored theme never animates in from the wrong
            colour, and flag the platform so the shortcut caps render ⌘ or
            Ctrl once rather than rendering one and correcting to the other. */}
        <script
          dangerouslySetInnerHTML={{
            __html:
              "if(/Mac|iPhone|iPad|iPod/.test(navigator.platform||navigator.userAgent))document.documentElement.classList.add('os-macos');" +
              "requestAnimationFrame(function(){requestAnimationFrame(function(){document.documentElement.classList.remove('preload')})})",
          }}
        />
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
        />
        <ThemeProvider>
          <ThemeColor />
          {/* One palette for the whole shell: the header's trigger and the
              dock's are two doors onto the same dialog, so the state sits
              above both rather than inside either. */}
          <CommandPaletteProvider items={paletteItems(posts)}>
            {/* `isolate` keeps the full-bleed hairlines (which paint at -z-1)
              above the page background instead of under it. */}
            <div className="group/layout relative isolate flex min-h-[100dvh] flex-col">
              <a
                href={FOCUSABLE_CHROME.skipToContentHref}
                className="skip-link"
              >
                {FOCUSABLE_CHROME.skipToContentLabel}
              </a>
              <SiteHeader hasPosts={hasPosts} />
              <main
                id={FOCUSABLE_CHROME.mainContentId}
                tabIndex={-1}
                className="flex max-w-screen flex-1 flex-col overflow-x-clip px-2 outline-none"
              >
                {/* A flex column so a short route (404, an empty state) can grow a
                  railed spacer down to the footer instead of leaving the frame
                  hanging in a void. */}
                <div className="mx-auto flex w-full flex-1 flex-col md:max-w-3xl">
                  {children}
                </div>
              </main>

              {/* Below `sm` this is the nav and the way into the palette. It
                  is mounted here, after the content it floats over, so the tab
                  order reaches it where the eye does. */}
              <MobileDock
                items={[{ label: "Home", href: "/" }, ...navItems(hasPosts)]}
              />

              <SiteFooter />

              {/* The bottom edge of the sheet. Ninety-six pixels of the page
                dissolving into the background, masked so the fade itself
                fades out rather than ending on a line, plus a solid strip
                under the home indicator. It is what keeps the last row of
                content from butting into the edge of the glass — and on a
                phone it is what the floating palette dock sits on. */}
              <div aria-hidden className="fade-bottom">
                <div className="fade-bottom-gradient" />
                <div className="fade-bottom-rest" />
              </div>

              {/* The way back up, riding on top of that fade. */}
              <ScrollToTop />
            </div>
          </CommandPaletteProvider>
        </ThemeProvider>
        <Analytics />
        <SpeedInsights />
      </body>
    </html>
  );
}

