import { cn } from "@/lib/utils";

/**
 * The page is a stack of panels sharing one vertical rail. A panel draws its
 * own left/right edges and a full-bleed hairline top and bottom, so the frame
 * continues past the content column to the edge of the viewport. Everything
 * on the site is composed from these six parts — there is no other container.
 */
export function Panel({ className, ...props }: React.ComponentProps<"section">) {
  return (
    <section
      data-slot="panel"
      className={cn(
        "screen-line-top screen-line-bottom border-x border-line",
        className,
      )}
      {...props}
    />
  );
}

export function PanelHeader({
  className,
  ...props
}: React.ComponentProps<"header">) {
  return (
    <header
      data-slot="panel-header"
      className={cn(
        "screen-line-bottom px-4 has-data-[slot=panel-description]:*:data-[slot=panel-title]:screen-line-bottom",
        className,
      )}
      {...props}
    />
  );
}

/**
 * A panel title is an `h2` because the usual panel is one section of a page
 * that already has its own `h1`. A page whose whole content *is* one panel —
 * a post, the blog index, the 404 — passes `as="h1"` so the document keeps a
 * top-level heading and the panel's own sub-headings still rank below it.
 */
export function PanelTitle({
  as: Tag = "h2",
  className,
  ...props
}: React.ComponentProps<"h2"> & { as?: "h1" | "h2" }) {
  return (
    <Tag
      data-slot="panel-title"
      className={cn(
        "group/panel-title font-heading text-3xl font-medium tracking-tight text-balance",
        className,
      )}
      {...props}
    />
  );
}

/** The count or unit that rides above the baseline of a title. */
export function PanelTitleSup({
  className,
  ...props
}: React.ComponentProps<"sup">) {
  return (
    <sup
      className={cn(
        "top-[-0.75em] ml-1 text-sm font-medium tracking-normal text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

export function PanelDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="panel-description"
      className={cn(
        "py-4 text-base text-balance text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

export function PanelContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div data-slot="panel-body" className={cn("p-4", className)} {...props} />
  );
}

--- SEARCH FIELD ---
"use client";

import { CloseIcon, SearchIcon } from "@/components/icons";

/**
 * The filter above a list. One field, used by the blog index and the projects
 * index, so the two pages type the same way — the second search box a Visitor
 * meets should teach them nothing new.
 *
 * It owns no state: the list it filters does, because the list is the thing
 * that has to re-render. See `PostSearch` and `ProjectSearch`.
 */
export function SearchField({
  value,
  onChange,
  label,
  placeholder,
}: {
  value: string;
  onChange: (value: string) => void;
  label: string;
  placeholder: string;
}) {
  return (
    <div className="screen-line-bottom p-2">
      <div className="relative flex items-center">
        <SearchIcon
          aria-hidden
          className="pointer-events-none absolute left-3 size-4 text-muted-foreground"
        />
        <input
          type="search"
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={(event) => {
            // Escape empties the field before it does anything else — the same
            // key the palette closes with, doing the same job here.
            if (event.key === "Escape" && value) {
              event.preventDefault();
              onChange("");
            }
          }}
          placeholder={placeholder}
          aria-label={label}
          autoComplete="off"
          spellCheck={false}
          /* 16px on a phone: anything smaller and iOS zooms the page on focus,
             which lands the Visitor somewhere they did not ask to be. */
          className="h-9 w-full rounded-lg border border-border bg-transparent pr-9 pl-9 text-base text-foreground placeholder:text-muted-foreground sm:text-sm dark:bg-input/30"
        />
        {value ? (
          <button
            type="button"
            onClick={() => onChange("")}
            aria-label="Clear search"
            className="absolute right-1.5 flex size-6 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:text-foreground"
          >
            <CloseIcon className="size-4" />
          </button>
        ) : null}
      </div>
    </div>
  );
}

/**
 * What a filter did, for someone who cannot see the list change shape. The
 * count is the whole message: a screen reader announcing every matching title
 * on every keystroke is worse than silence.
 */
export function SearchStatus({
  count,
  noun,
}: {
  count: number;
  noun: string;
}) {
  return (
    <p role="status" className="sr-only">
      {count === 1 ? `1 ${noun}` : `${count} ${noun}s`}
    </p>
  );
}

