/* ---------------------------------------------------------------------------
   Chrome
--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--background);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
  translate: -50% 0;
}

/* ---------------------------------------------------------------------------
   Typeset — the two long-form measures. `--typeset-flow` is the vertical
   rhythm between blocks, expressed in the block's own em so it scales with
   the measure rather than the root.
--------------------------------------------------------------------------- */

.typeset {
  --typeset-size: 1rem;
  --typeset-leading: 1.65;
  --typeset-flow: 1.25em;

  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
  text-wrap: pretty;
}

.typeset > * + * {
  margin-top: var(--typeset-flow);
}

.typeset-description {
  --typeset-size: 15px;
  --typeset-leading: 1.6;
  --typeset-flow: 1em;
}

.typeset-timescale {
  --typeset-size: 0.875rem;
  --typeset-leading: 1.5;
  --typeset-flow: 1em;
}

/* ---------------------------------------------------------------------------
   Entrance. The frame is drawn instantly; only the mosaic and the palette
   fade, and neither loops.
--------------------------------------------------------------------------- */

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Written out rather than run as `fade-in … reverse`: reversing an animation
   that has already finished does not restart it, it re-reads the same finished
   playhead against the other end of the timeline — so the element snaps to the
   far keyframe instead of travelling to it. An exit needs its own name. */
@keyframes fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

/* ---------------------------------------------------------------------------
   Activity mosaic. Square blocks on a 2px gutter, no corner rounding — the
   grid is a measuring instrument, so its cells are not decorated. Intensity
   is carried by the neutral foreground at five opacities.

   Every measurement here is the reference's: a 12px block on a 2px gutter,
   under a 22px label band. They are not arbitrary — a rolling year at that
   size is a fixed 740px plate, the same shape every month of every year, which
   is the whole point of drawing a habit as a calendar. A cell that grew to
   fill the rail would make the same year a different picture each visit.
--------------------------------------------------------------------------- */

.activity-grid {
  --cell-size: 12px;
  --cell-gap: 2px;
  --label-size: 12px;
  display: grid;
  /* A length, not a fraction. A `1fr` track lets the browser round one week
     to 12px and the next to 13, which on a grid of squares reads as a wobble
     in every row. */
  grid-template-columns: repeat(var(--weeks, 53), var(--cell-size));
  gap: var(--cell-gap);
  /* The grid is one tab stop, but the thing that moves is the active cell, so
     the ring is drawn there instead of around all 365 of them. */
  outline: none;
  /* Room for that ring, so it cannot cross the panel's vertical rail. */
  padding-inline: 3px;
}

.activity-col {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7, var(--cell-size));
  gap: var(--cell-gap);
  /* The label band: the type size plus the 8px of air the reference leaves
     under it, so the months sit above the plate rather than on it. */
  padding-top: calc(var(--label-size) + 8px);
}

/* Sits above its own column, allowed to overflow it. */
.activity-month {
  position: absolute;
  top: 0;
  left: 0;
  font-family: var(--font-mono);
  font-size: var(--label-size);
  line-height: 1;
  color: var(--muted-foreground);
  white-space: nowrap;
  pointer-events: none;
}

/* The strip is wider than a phone, so it is dragged rather than trimmed. The edge fades are driven by the scroll position itself: each side
   is masked only while there is more grid past it, so a strip that fits shows
   no fade at all and a strip scrolled to its end stops advertising an end. */
@property --activity-fade-s {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@property --activity-fade-e {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@keyframes activity-fade-s {
  from {
    --activity-fade-s: 0px;
  }
  to {
    --activity-fade-s: var(--activity-fade);
  }
}
@keyframes activity-fade-e {
  from {
    --activity-fade-e: var(--activity-fade);
  }
  to {
    --activity-fade-e: 0px;
  }
}

.activity-scroll {
  --activity-fade: 2.5rem;
  display: flex;
  /* The same gutter every other row in the panel keeps, so the first and last
     week line up with the caption above them rather than with the rail. */
  padding-inline: 1rem;
  /* Centred while the year fits the rail, flush-left once it does not —
     `safe` is what keeps the first week reachable instead of centring it off
     the scrollable edge. */
  justify-content: safe center;
  overflow-x: auto;
  overflow-y: hidden;
  /* The grid is a drawing; a scrollbar drawn under it would read as part of
     the figure. The strip still scrolls by drag, wheel and keyboard. */
  scrollbar-width: none;
  mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 var(--activity-fade-s),
    #000 calc(100% - var(--activity-fade-e)),
    transparent 100%
  );
  animation:
    activity-fade-s 1ms linear both,
    activity-fade-e 1ms linear both;
  animation-timeline: scroll(self inline), scroll(self inline);
  animation-range:
    0 var(--activity-fade),
    calc(100% - var(--activity-fade)) 100%;
}

.activity-scroll::-webkit-scrollbar {
  display: none;
}

.activity-cell {
  background: color-mix(
    in oklab,
    var(--muted-foreground) var(--level, 10%),
    transparent
  );
  position: relative;
  width: var(--cell-size);
  height: var(--cell-size);
  animation: fade-in 260ms var(--ease-out-quint) both;
  animation-delay: calc(var(--col, 0) * 5ms + 320ms);
  /* No transition on the marker. A cursor that fades in over a tenth of a
     second reads as the grid thinking about it; the cursor is where the
     pointer is, and that is true on the frame the pointer arrives. */
  outline: 1px solid transparent;
  outline-offset: 1px;
}

/* Pointer: a hairline marker. Keyboard: the site's own focus ring, moved onto
   the active descendant so focus keeps the same shape it has everywhere else. */
.activity-cell[data-active="true"] {
  outline-color: var(--foreground);
}

.activity-grid:focus-visible .activity-cell[data-active="true"] {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}

/* An empty frame rather than a fill. Only Figure 404 draws these now: inside
   the activity window an absent day is a measured zero, because the meter
   reads every session on the machine. */
.activity-cell[data-recorded="false"] {
  background: transparent;
  box-shadow: inset 0 0 0 1px
    color-mix(in oklab, var(--muted-foreground) 16%, transparent);
}

/* ---------------------------------------------------------------------------
   A single sweep of light across a line of text, once, on load. The gradient
   is painted into the glyphs themselves and slid from right to left, so the
   highlight travels the line rather than the line changing colour. Spread is
   in `ch` so it scales with the type, and the background is twice the element
   plus two spreads wide so the sweep starts and ends fully off the text.
--------------------------------------------------------------------------- */
@keyframes shimmer-sweep {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: 0 0;
  }
}

.shimmer {
  --shimmer-spread: calc(3ch + 40px);
  --shimmer-angle: 20deg;
  background-image: linear-gradient(
    calc(90deg + var(--shimmer-angle)),
    currentColor calc(50% - var(--shimmer-spread)),
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% - var(--shimmer-spread) * 0.5),
    var(--foreground) 50%,
    color-mix(in oklch, var(--foreground), currentColor 50%)
      calc(50% + var(--shimmer-spread) * 0.5),
    currentColor calc(50% + var(--shimmer-spread))
  );
  background-repeat: no-repeat;
  background-size: calc(200% + var(--shimmer-spread) * 2) 100%;
  background-position: 0 0;
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: shimmer-sweep 1.5s linear 1;
}

/* Motion is the whole effect, so with it turned off there is nothing left to
   show — paint the text normally rather than leaving it in a frozen gradient. */
@media (prefers-reduced-motion: reduce) {
  .shimmer {
    background-image: none;
    animation: none;
    -webkit-text-fill-color: currentColor;
  }
}

/* ---------------------------------------------------------------------------
   Name pronunciation. The speaker's two waves pulse while the name is being
   said, offset so they read as leaving the cone rather than blinking together.
   Nothing else moves: the glyph is the state, so it must not also be a toy.
--------------------------------------------------------------------------- */
@keyframes pronounce-wave {
  0%,
  100% {
    opacity: 0.3;
  }
  50% {
    opacity: 1;
  }
}

[data-slot="pronounce"][data-speaking] [data-wave="near"] {
  animation: pronounce-wave 0.9s ease-in-out infinite;
}

[data-slot="pronounce"][data-speaking] [data-wave="far"] {
  animation: pronounce-wave 0.9s ease-in-out 0.15s infinite;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="pronounce"][data-speaking] [data-wave] {
    animation: none;
  }
}

/* ---------------------------------------------------------------------------
   The bottom edge of the sheet. Fixed, so it is the last thing every scroll
   runs into: the page dissolves into the background over six rems, and the
   gradient is itself masked from the top so the fade has no visible start.
   The strip below it is opaque background padded by the home indicator, which
   is what the floating palette dock rests on.
--------------------------------------------------------------------------- */
.fade-bottom {
  position: fixed;
  inset-inline: 0;
  bottom: 0;
  z-index: 50;
  pointer-events: none;
}

.fade-bottom-gradient {
  height: var(--fade-bottom-height);
  background: linear-gradient(to bottom, transparent, var(--background));
  mask-image: linear-gradient(to top, var(--background) 25%, transparent);
  backdrop-filter: blur(1px);
}

.fade-bottom-rest {
  background: var(--background);
  padding-bottom: env(safe-area-inset-bottom, 0px);
}

/* ---------------------------------------------------------------------------
   Figure 404. Drawn from the same cells as the activity grid, at plate scale:
   the page that has no data says so in the site's own word for it. Cells size
   themselves off the column rather than off a fixed pixel, so the plate is the
   full width of the frame at every viewport.
--------------------------------------------------------------------------- */
.glyph-grid {
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
  gap: 2px;
  width: 100%;
}

.glyph-grid > * {
  aspect-ratio: 1;
}

/* ---------------------------------------------------------------------------
   Prose (MDX) — long-form runs on the serif; structure stays sans.
--------------------------------------------------------------------------- */

.prose {
  /* One step up from the interface size. The serif runs to ~76 characters at
     16px in this frame, which is past the line a reader can return from
     without losing their place; the extra pixel pulls it back to ~72. */
  --typeset-size: 1.0625rem;
  font-family: var(--font-serif);
  color: var(--foreground);
}
.prose h2,
.prose h3 {
  font-family: var(--font-heading);
  font-weight: 500;
  letter-spacing: -0.01em;
  scroll-margin-top: calc(var(--header-height) + 1rem);
}
.prose h2 {
  font-size: 1.5rem;
  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
}
.prose > :first-child {
  margin-top: 0;
}
.prose a {
  color: var(--link);
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: text-decoration-color 150ms var(--ease-out-quint);
}
.prose a:hover {
  text-decoration-color: currentColor;
}
.prose strong {
  font-weight: 600;
}
.prose ul,
